  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Creates a new IPO application for this retail customer by providing the target company, number of shares, payment amount, and a non-null allowance document. The customer must be currently eligible and must not already have an approved application for the same company name.
   * Algorithm:
   * 1. Validate inputs:
   *    - company is not null
   *    - shares > 0
   *    - amount > 0
   *    - doc is not null
   * 2. Check whether this customer is eligible for IPO.
   * 3. Check whether this customer already has an approved application for the same company name.
   * 4. If any validation fails, return false.
   * 5. Create a new Application with status PENDING, the given company, shares, amount, document, and this customer.
   * 6. Add the new Application to applications.
   * 7. Return true.
   * Related Features:
   * - applications
   * - canApplyForIPO
   * - email
   * - name
   * - surname
   * - telephone
   * - createApplication(company : Company, shares : int, amount : double, doc : Document) : boolean
   * - isEligibleForIPO() : boolean
   * - cancelApplication(companyName : String) : boolean
   * Related Classes:
   * Application, Company, Document, ApplicationStatus
   * Input:
   * - company : Company
   *   - target company for the IPO application.
   *   - Must be non-null.
   * - shares : int
   *   - number of shares requested.
   *   - Must be greater than 0.
   * - amount : double
   *   - payment amount to be paid.
   *   - Must be greater than 0.
   * - doc : Document
   *   - legal allowance document.
   *   - Must be non-null and contain a name identifying the allowance document.
   * Output:
   * - boolean:
   *   - true if the application record is created and stored successfully.
   *   - false otherwise.
   * Pre-condition:
   * - This customer is a retail customer eligible to apply or may become eligible according to business state.
   * - company, doc are not null.
   * - shares > 0.
   * - amount > 0.
   * - The customer does not already have an approved application for the same company name.
   * Post-condition:
   * - If return value is true:
   *   - a new pending application is added to applications.
   *   - the new application references this customer, the target company, and the allowance document.
   * - If return value is false:
   *   - applications list is unchanged.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean createApplication(final Company company, final int shares, final double amount, final Document doc)
  {
    if (company == null || doc == null || shares <= 0 || amount <= 0 || !isEligibleForIPO())
    {
      return false;
    }

    String companyName = company.getName();
    for (Application application : getApplications())
    {
      if (application.getStatus() == ApplicationStatus.APPROVAL
          && application.getCompany() != null
          && application.getCompany().getName() != null
          && application.getCompany().getName().equals(companyName))
      {
        return false;
      }
    }

    Application application = IpoFactory.eINSTANCE.createApplication();
    application.setStatus(ApplicationStatus.PENDING);
    application.setCompany(company);
    application.setShare(shares);
    application.setAmountOfMoney(amount);
    application.setAllowance(doc);
    application.setCustomer(this);
    getApplications().add(application);
    return true;
    
  }

